new DataTable('#example', {
	layout: {
		topStart: {
			buttons: ['statesList', 'pageLength']
		}
	},
	stateRestore: {
		canCreate: false,
		predefined: [
			{
				name: 'Summary columns',
				state: {
					columns: [
						{visible: true},
						{visible: true},
						{visible: true},
						{visible: false},
						{visible: false},
						{visible: false}
					]
				}
			},
			{
				name: 'All columns',
				state: {
					columns: [
						{visible: true},
						{visible: true},
						{visible: true},
						{visible: true},
						{visible: true},
						{visible: true}
					]
				}
			}
		]
	}
});
